#requires -Version 5.1
<# Created by Dewald Pretorius. Read-only local privilege escalation risk validator. #>
[CmdletBinding()]param([string]$OutputPath=(Join-Path ([Environment]::GetFolderPath('Desktop')) 'Privilege_Escalation_Validation'))
$ErrorActionPreference='Stop';New-Item -ItemType Directory $OutputPath -Force|Out-Null;$s=Get-Date -Format yyyyMMdd_HHmmss
try{$services=@(Get-CimInstance Win32_Service|Where-Object{$_.PathName -match '^\s*[^"].*\s+.*\.exe' -and $_.PathName -notmatch '^\s*"'}|Select-Object Name,StartName,State,PathName);$aie=@([pscustomobject]@{Scope='Machine';Enabled=((Get-ItemProperty 'HKLM:\Software\Policies\Microsoft\Windows\Installer' -Name AlwaysInstallElevated -ErrorAction SilentlyContinue).AlwaysInstallElevated-eq1)},[pscustomobject]@{Scope='User';Enabled=((Get-ItemProperty 'HKCU:\Software\Policies\Microsoft\Windows\Installer' -Name AlwaysInstallElevated -ErrorAction SilentlyContinue).AlwaysInstallElevated-eq1)});[ordered]@{Generated=(Get-Date);UnquotedServicePathCount=$services.Count;UnquotedServices=$services;AlwaysInstallElevated=$aie}|ConvertTo-Json -Depth 6|Set-Content (Join-Path $OutputPath "risk_$s.json");if($services.Count-or@($aie|Where-Object Enabled).Count){exit 1};exit 0}catch{Write-Error $_;exit 5}
